limit_req_zone  $binary_remote_addr zone=login:10m rate=5r/m;
limit_req_zone  $binary_remote_addr zone=search:10m rate=10r/s;
limit_conn_zone $binary_remote_addr zone=perip:10m;
limit_req_status  429;
limit_conn_status 429;

map $request_method $method_ok { default 0; GET 1; HEAD 1; POST 1; }

server {
    listen 443 ssl;
    server_name shop.example.com;

    client_max_body_size   1m;      # reject big bodies early
    client_header_timeout  10s;     # slow header senders are cut off
    client_body_timeout    10s;
    limit_conn perip 20;

    if ($method_ok = 0) { return 405; }

    location = /login {
        limit_req zone=login burst=3 nodelay;
        proxy_pass http://10.0.0.20:8080;
    }
    location /api/search {
        limit_req zone=search burst=20 nodelay;
        proxy_pass http://10.0.0.20:8080;
    }
}

